//! `cargo xtask notices`: the THIRD-PARTY-NOTICES each shipped artifact
//! carries, generated by cargo-about from `crates/about.toml` and
//! `crates/about.hbs` into `<target>/dist/notices/<artifact>/`.
//!
//! Each artifact is scanned as its own package for its own target, so the
//! wasm notices list what links into the wasm and the native ones what links
//! into the binary, not the union of the workspace. The run is `--offline`
//! and `--locked`, so the text comes from the crate sources cargo already
//! verified rather than from whatever a crate's repository serves today, and
//! `--fail` refuses a crate whose license cannot be read.

use std::path::Path;
use std::process::Command;

use crate::metadata::{self, WASM_TARGET};

const ABOUT_VERSION: &str = "0.9.3";

/// `(artifact, manifest, target triple, a crate its notices must name)`.
fn artifacts(host: &str) -> [(&'static str, &'static str, String, Option<&'static str>); 2] {
    [
        ("wasm", "crates/bindings/wasm/Cargo.toml", WASM_TARGET.to_owned(), Some("wasm-bindgen")),
        // The fixture has no dependencies, so its notices carry only the
        // standard-library paragraph; nothing can be required of it.
        ("native", "crates/bindings/native-fixture/Cargo.toml", host.to_owned(), None),
    ]
}

/// The quoted strings of the first `key = [ ... ]` array after `section`.
pub(crate) fn string_array(toml: &str, section: &str, key: &str) -> Vec<String> {
    let body = toml.split_once(section).map_or("", |(_, rest)| rest);
    let Some((_, rest)) = body.split_once(&format!("{key} = [")) else {
        return Vec::new();
    };
    let array = rest.split_once(']').map_or(rest, |(a, _)| a);
    array
        .lines()
        .map(|l| l.split('#').next().unwrap_or_default())
        .flat_map(|l| l.split('"').skip(1).step_by(2).map(str::to_owned).collect::<Vec<_>>())
        .collect()
}

fn host_triple() -> Result<String, Vec<String>> {
    let out = Command::new("rustc")
        .arg("-vV")
        .output()
        .map_err(|e| vec![format!("rustc did not run: {e}")])?;
    String::from_utf8_lossy(&out.stdout)
        .lines()
        .find_map(|l| l.strip_prefix("host: ").map(str::to_owned))
        .ok_or_else(|| vec!["rustc -vV names no host".to_owned()])
}

pub(crate) fn run() -> Result<Vec<String>, Vec<String>> {
    let installed = Command::new(metadata::cargo()).args(["about", "--version"]).output();
    let version = installed
        .ok()
        .filter(|o| o.status.success())
        .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_owned());
    if version.as_deref() != Some(&format!("cargo-about {ABOUT_VERSION}")) {
        return Err(vec![format!(
            "notices: cargo-about {ABOUT_VERSION} is required, found {}. Install it with:\n  cargo install --locked cargo-about --version {ABOUT_VERSION} --features cli",
            version.unwrap_or_else(|| "none".to_owned())
        )]);
    }
    let meta = metadata::load()?;
    let root = &meta.workspace_root;
    let allowed = string_array(&read(&root.join("deny.toml"))?, "[licenses]", "allow");
    let accepted = string_array(&read(&root.join("crates/about.toml"))?, "", "accepted");
    if allowed.is_empty() || accepted != allowed {
        return Err(vec![format!(
            "notices: crates/about.toml accepts {accepted:?} but deny.toml allows {allowed:?}; keep them equal"
        )]);
    }
    let mut lines = Vec::new();
    for (name, manifest, target, must_name) in artifacts(&host_triple()?) {
        let dir = meta.target_directory.join("dist").join("notices").join(name);
        std::fs::create_dir_all(&dir)
            .map_err(|e| vec![format!("cannot create {}: {e}", dir.display())])?;
        let out = dir.join("THIRD-PARTY-NOTICES");
        let status = Command::new(metadata::cargo())
            .current_dir(root)
            .args([
                "about",
                "generate",
                "--locked",
                "--offline",
                "--fail",
                "-c",
                "crates/about.toml",
                "-m",
                manifest,
            ])
            .args(["--target", &target, "-o"])
            .arg(&out)
            .arg("crates/about.hbs")
            .status()
            .map_err(|e| vec![format!("cargo about did not run: {e}")])?;
        if !status.success() {
            return Err(vec![format!("notices: cargo about generate for {name} failed: {status}")]);
        }
        let text = read(&out)?;
        if let Some(krate) = must_name
            && !text.contains(&format!("  - {krate} "))
        {
            return Err(vec![format!(
                "notices: {name}'s notices do not name {krate}, which it links; the scan missed its dependencies"
            )]);
        }
        lines.push(format!("notices: {} ({} bytes)", out.display(), text.len()));
    }
    Ok(lines)
}

fn read(path: &Path) -> Result<String, Vec<String>> {
    std::fs::read_to_string(path).map_err(|e| vec![format!("cannot read {}: {e}", path.display())])
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn string_array_reads_a_commented_multiline_array() {
        let toml = "[other]\nallow = [\"no\"]\n[licenses]\nallow = [\n  \"MIT\",\n  # why\n  \"Zlib\", # inline\n]\n";
        assert_eq!(string_array(toml, "[licenses]", "allow"), ["MIT", "Zlib"]);
    }

    #[test]
    fn the_notices_accept_exactly_the_licenses_cargo_deny_admits() {
        let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
        let deny = std::fs::read_to_string(root.join("deny.toml")).unwrap();
        let about = std::fs::read_to_string(root.join("crates/about.toml")).unwrap();
        let allowed = string_array(&deny, "[licenses]", "allow");
        assert!(allowed.len() >= 3, "{allowed:?}");
        assert_eq!(string_array(&about, "", "accepted"), allowed);
    }
}
